//! Identifier encoding and edit-secret hashing.
//!
//! View ids and edit secrets are 128-bit random values (generated by the caller with an OS-backed
//! CSPRNG) encoded as fixed-width base62, so they are URL-safe and always [`ID_LEN`] characters.

use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

const ALPHABET: &[u8; 62] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

/// Length of an encoded 128-bit id: 62^22 > 2^128 > 62^21.
pub const ID_LEN: usize = 22;

/// Encode 128 random bits as exactly [`ID_LEN`] base62 characters (left-padded with '0').
pub fn encode_base62(mut n: u128) -> String {
    let mut out = [b'0'; ID_LEN];
    for slot in out.iter_mut().rev() {
        *slot = ALPHABET[(n % 62) as usize];
        n /= 62;
    }
    // Every byte comes from ALPHABET, so this is always valid ASCII.
    String::from_utf8(out.to_vec()).expect("base62 is ASCII")
}

/// True if `s` looks like an id we could have issued: exactly [`ID_LEN`] ASCII alphanumerics.
/// Used to reject junk in URLs before touching the store.
pub fn is_valid_id(s: &str) -> bool {
    s.len() == ID_LEN && s.bytes().all(|b| b.is_ascii_alphanumeric())
}

/// Hex SHA-256 of an edit secret. Only this hash is stored.
///
/// A plain (unsalted, fast) hash is fine here because the secret is 128 random bits, not a
/// password: there is nothing to brute-force.
pub fn hash_secret(secret: &str) -> String {
    hex::encode(Sha256::digest(secret.as_bytes()))
}

/// Check an edit secret against a stored hash in constant time, so response timing reveals
/// nothing about how much of the hash matched.
pub fn verify_secret(secret: &str, stored_hash: &str) -> bool {
    let candidate = hash_secret(secret);
    // Both are 64 hex chars when the stored hash is well formed; `ct_eq` returns false for
    // different lengths.
    candidate.as_bytes().ct_eq(stored_hash.as_bytes()).into()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn base62_is_fixed_width() {
        assert_eq!(encode_base62(0), "0".repeat(ID_LEN));
        assert_eq!(encode_base62(61), format!("{}z", "0".repeat(ID_LEN - 1)));
        let max = encode_base62(u128::MAX);
        assert_eq!(max.len(), ID_LEN);
        assert!(is_valid_id(&max));
        assert!(is_valid_id(&encode_base62(12345678901234567890)));
    }

    #[test]
    fn rejects_bad_ids() {
        assert!(!is_valid_id(""));
        assert!(!is_valid_id(&"a".repeat(ID_LEN - 1)));
        assert!(!is_valid_id(&"a".repeat(ID_LEN + 1)));
        assert!(!is_valid_id(&format!("{}-", "a".repeat(ID_LEN - 1))));
        assert!(!is_valid_id(&format!("{}é", "a".repeat(ID_LEN - 2))));
    }

    #[test]
    fn secret_round_trip() {
        let h = hash_secret("abc");
        assert_eq!(h.len(), 64);
        assert!(verify_secret("abc", &h));
        assert!(!verify_secret("abd", &h));
        assert!(!verify_secret("abc", ""));
    }
}
